// Minimal MCP server in TypeScript using the official SDK (stdio transport).
// One tool, one resource — enough to make the wire format concrete.
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';

const server = new McpServer({
  name: 'llm-lab-example',
  version: '0.1.0',
});

// 1. A tool — model can invoke it.
server.registerTool(
  'add',
  {
    description: 'Add two integers. IDEMPOTENT. READ-ONLY.',
    inputSchema: { a: z.number().int(), b: z.number().int() },
  },
  async ({ a, b }) => ({
    content: [{ type: 'text', text: String(a + b) }],
  }),
);

// 2. A resource — client reads, model is informed.
server.registerResource(
  'greeting',
  'greeting://welcome',
  {
    title: 'Welcome',
    description: 'A static welcome message.',
    mimeType: 'text/plain',
  },
  async () => ({
    contents: [{
      uri: 'greeting://welcome',
      mimeType: 'text/plain',
      text: 'Hello from the example MCP server.',
    }],
  }),
);

const transport = new StdioServerTransport();
await server.connect(transport);
